def max_gap_between_elements(lst):
    if len(lst) < 2:
        return 0
    s = sorted(lst)
    return max(s[i + 1] - s[i] for i in range(len(s) - 1))

def count_local_maxima_including_endpoints(lst):
    n = len(lst)
    if n == 0:
        return 0
    if n == 1:
        return 1
    count = 0
    if lst[0] > lst[1]:
        count += 1
    if lst[n - 1] > lst[n - 2]:
        count += 1
    for i in range(1, n - 1):
        if lst[i] > lst[i - 1] and lst[i] > lst[i + 1]:
            count += 1
    return count

def trim_leading_trailing_zeros(lst):
    start = 0
    end = len(lst)
    while start < end and lst[start] == 0:
        start += 1
    while end > start and lst[end - 1] == 0:
        end -= 1
    return lst[start:end]

def first_index_running_sum_exceeds(lst, target):
    total = 0
    for i, x in enumerate(lst):
        total += x
        if total > target:
            return i
    return -1

def running_sum_reset_on_negative(lst):
    res = []
    total = 0
    for x in lst:
        total += x
        if total < 0:
            total = 0
        res.append(total)
    return res

def longest_positive_run_sum(lst):
    best_len = 0
    best_sum = 0
    cur_len = 0
    cur_sum = 0
    for x in lst:
        if x > 0:
            cur_len += 1
            cur_sum += x
        else:
            if cur_len > best_len:
                best_len = cur_len
                best_sum = cur_sum
            cur_len = 0
            cur_sum = 0
    if cur_len > best_len:
        best_sum = cur_sum
    return best_sum

def interleave_two_sorted_lists(a, b):
    i = j = 0
    res = []
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            res.append(a[i])
            i += 1
        else:
            res.append(b[j])
            j += 1
    res.extend(a[i:])
    res.extend(b[j:])
    return res

def median_of_list(lst):
    s = sorted(lst)
    n = len(s)
    mid = n // 2
    if n % 2 == 1:
        return s[mid]
    else:
        return round((s[mid - 1] + s[mid]) / 2, 1)

def shift_right_and_fill(lst, n, fill):
    length = len(lst)
    if n <= 0:
        return lst[:]
    if n >= length:
        return [fill] * length
    return [fill] * n + lst[:length - n]

def shift_left_and_fill(lst, n, fill):
    length = len(lst)
    if n <= 0:
        return lst[:]
    if n >= length:
        return [fill] * length
    return lst[n:] + [fill] * n

def first_missing_positive(lst):
    s = set(lst)
    i = 1
    while i in s:
        i += 1
    return i

def compress_ranges(lst):
    if not lst:
        return []
    res = []
    start = prev = lst[0]
    for x in lst[1:]:
        if x == prev + 1:
            prev = x
        else:
            res.append([start, prev])
            start = prev = x
    res.append([start, prev])
    return res

def expand_ranges(pairs):
    result = set()
    for start, end in pairs:
        for x in range(start, end + 1):
            result.add(x)
    return sorted(result)

def max_product_of_two(lst):
    s = sorted(lst)
    return max(s[-1] * s[-2], s[0] * s[1])

def min_absolute_difference_pair(lst):
    s = sorted(lst)
    return min(s[i + 1] - s[i] for i in range(len(s) - 1))

def count_inversions(lst):
    n = len(lst)
    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            if lst[i] > lst[j]:
                count += 1
    return count

def longest_common_prefix_length(list_of_lists):
    if not list_of_lists:
        return 0
    min_len = min(len(l) for l in list_of_lists)
    count = 0
    for i in range(min_len):
        val = list_of_lists[0][i]
        if all(l[i] == val for l in list_of_lists):
            count += 1
        else:
            break
    return count

def remove_elements_at_indices(lst, indices):
    remove_set = set(indices)
    return [x for i, x in enumerate(lst) if i not in remove_set]

def insert_at_intervals(lst, item, interval):
    res = []
    n = len(lst)
    for i, x in enumerate(lst, start=1):
        res.append(x)
        if i % interval == 0 and i != n:
            res.append(item)
    return res
